    now:'2026-09-19T12:00:00Z',
    queueInput:{maxConcurrentTasks:32,tasks:[
      {id:'stale',gameId:'a',target:'web',goal:'x',status:'running',reservedAt:'2026-09-19T10:00:00Z'},
